-- 栈应用：表达式转换和后缀求值中的操作数顺序。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '表达式转换与求值','运算符栈按优先级和括号进出，后缀求值必须先弹右操作数再弹左操作数。',course.id,parent.id,'cs408-expression-evaluation','AISTU',1,'REVIEWED',6,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-expression-evaluation' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-expression-evaluation',1,'REVIEWED','表达式转换与求值',JSON_OBJECT('summary','中缀转后缀时直接输出运算数，运算符按优先级、结合性和括号规则进出栈；后缀求值时运算数入栈，遇二元运算符依次弹出右、左操作数计算后压回。弹出顺序不能颠倒。','steps',JSON_ARRAY('中缀表达式的运算数直接输出','运算符按优先级、结合性和括号规则进出栈','后缀表达式的运算数压入操作数栈','二元运算符先弹右操作数，再弹左操作数','计算结果压回栈顶等待后续运算'),'prerequisite',JSON_OBJECT('contentKey','cs408-stack-lifo','title','栈的 LIFO 语义与基本操作','description','先掌握栈顶先出的读取顺序。'),'nextStep',JSON_OBJECT('contentKey','cs408-recursion-call-stack','title','递归与调用栈','description','继续从活动记录入栈和逐层返回理解 LIFO。')),JSON_OBJECT('id','expression-evaluation-v1','prompt','后缀表达式求值遇到二元运算符时，应如何取得两个操作数？','options',JSON_ARRAY(JSON_OBJECT('id','RIGHT_THEN_LEFT','text','先弹出右操作数，再弹出左操作数'),JSON_OBJECT('id','LEFT_THEN_RIGHT','text','先弹出左操作数，再弹出右操作数')),'correctOptionId','RIGHT_THEN_LEFT','correctExplanation','正确：栈顶保存的是表达式中较晚压入的右操作数，减法和除法尤其不能颠倒。','incorrectExplanation','不正确：先将栈顶当作左操作数会改变非交换运算的语义。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-expression-evaluation' AND existing.content_version=1 WHERE point.content_key='cs408-expression-evaluation' AND existing.id IS NULL;
